function [w_M, tau_L] = mfun_cvc_speed_observer(eps, tau_M, p)
%MFUN_CVC_SPEED_OBSERVER Block SpeedObserver of the control system.
%   SpeedObserver of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the Simulink model, which adds
%   its folder to the MATLAB path. The parameters are the fields of the struct p (from
%   the mask, [] as NaN). The state is in persistent variables, of which each MATLAB
%   Function block has its own copy. The inputs without direct feedthrough come through
%   unit delays, so the update of the state with them is done at the next call.
persistent self pending
if isempty(self)
    % The mechanical system model is not used without J
    J = p.J;
    if isnan(J)
        J = 0;
    end
    self = speed_observer_init(p.k_w, p.k_tau, J);
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% eps, tau_M through unit delays)
if pending
    self = speed_observer_update(self, p.T_s, eps, tau_M);
end
pending = true;
w_M = self.w_M;
tau_L = self.tau_L;
end

function self = speed_observer_init(k_w, k_tau, J)
%SPEED_OBSERVER_INIT Speed observer (SpeedObserver); the mechanical system model is
%   used if J > 0.
self = struct('k_w', k_w, 'k_tau', k_tau, 'J', J, 'w_M', 0, 'tau_L', 0);
end

function self = speed_observer_update(self, T_s, eps, tau_M)
%SPEED_OBSERVER_UPDATE Update the speed and load torque estimates.
if self.J <= 0
    d_w_M = self.k_w*eps;
    d_tau_L = 0;
else
    d_w_M = (tau_M - self.tau_L)/self.J + self.k_w*eps;
    d_tau_L = -self.k_tau*eps;
end
self.w_M = self.w_M + T_s*d_w_M;
self.tau_L = self.tau_L + T_s*d_tau_L;
end
